import Crypto
import Foundation
import Testing
@testable import ViadereCore

/// Cross-language test vectors (`docs/protocol/vectors/*.json`). Each file is the contract another client (Android, a business SDK in another
/// language) must reproduce byte for byte: the signing inputs are recomputed from the inputs and compared, and every signature is verified.
///
/// The files are generated by this target: `VIADERE_WRITE_VECTORS=1 swift test --filter ProtocolVectorTests` rewrites them. Without that
/// variable the test only reads and checks them, so an encoding that drifts fails here.
@Suite("Protocol vectors")
struct ProtocolVectorTests {
    static var vectorsDirectory: URL {
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0..<5 { url.deleteLastPathComponent() }
        return url.appendingPathComponent("docs/protocol/vectors")
    }

    /// A fixed key: SHA-256 of a label is a valid P-256 scalar for these labels (checked by construction).
    static func fixedKey(_ label: String) throws -> SoftwareP256SigningKey {
        try SoftwareP256SigningKey(rawRepresentation: Data(SHA256.hash(data: Data("viadere-vector-\(label)".utf8))))
    }

    struct KeyVector: Codable, Equatable {
        var purpose: String
        var algorithm: String
        var publicKey: String
        var proofMessage: String
        var proof: String
    }

    struct AccountEnrollmentVectors: Codable, Equatable {
        var name: String
        var version: Int
        var description: String
        var accountId: String
        var challenge: String
        var keys: [KeyVector]
        var keyListDigest: String
        var appAttestClientData: String
        var appAttestClientDataHashHex: String
        var recoveryCredentialProof: ProofVector
    }

    struct ProofVector: Codable, Equatable {
        var subject: String
        var subjectId: String
        var deviceId: String
        var signedAt: String
        var assurance: String
        var publicKey: String
        var signingInput: String
        var signature: String
    }

    static let accountId = ConsumerID(UUID(uuidString: "6f1c2a4e-9b3d-4c5e-8f70-112233445566")!)
    static let challenge = "Q2hhbGxlbmdlLWZvci1hY2NvdW50LWVucm9sbG1lbnQtdmVjdG9y"
    static let ceremonyId = "0b4f8c1a-2d3e-4f50-9a6b-7c8d9e0f1a2b"
    static let deviceId = DeviceID(UUID(uuidString: "a1b2c3d4-e5f6-4789-8abc-def012345678")!)
    static let signedAt = Date(timeIntervalSince1970: 1_800_000_000.123)

    static func generate() async throws -> AccountEnrollmentVectors {
        var keys: [KeyVector] = []
        var registrations: [DeviceKeyRegistration] = []
        for purpose in DeviceKeyPurpose.allCases {
            let key = try fixedKey(purpose.rawValue)
            let registration = try await DeviceEnrollment.register(key: key, purpose: purpose, hardwareBacked: true, consumerId: accountId, challenge: challenge)
            registrations.append(registration)
            let message = DeviceEnrollment.proofMessage(consumerId: accountId, challenge: challenge, purpose: purpose, publicKey: key.publicKey)
            keys.append(KeyVector(purpose: purpose.rawValue, algorithm: registration.algorithm.rawValue, publicKey: key.publicKey.base64URL,
                                  proofMessage: String(decoding: message, as: UTF8.self), proof: registration.proof))
        }
        let passcode = try fixedKey(DeviceKeyPurpose.approvalUserPresence.rawValue)
        let proof = try await ConfirmationProof.sign(subject: .recoveryCredential, subjectId: ceremonyId, deviceId: deviceId, assurance: .devicePasscode,
                                                     key: passcode, now: signedAt)
        return AccountEnrollmentVectors(
            name: "account-enrollment-v1", version: 1,
            description: "Device-first account creation (SECURITY.md 2.5a): key proofs (VIADERE-ENROLL-V1) and the App Attest client data (VIADERE-APPATTEST-ENROLL-V1) over the reserved account id, and the user-verified proof that adds a recovery credential (VIADERE-CONFIRM-V1, subject recoveryCredential, subjectId = the server ceremony id). Signatures are ECDSA P-256 / SHA-256, raw r||s, base64url, low-S; verify them, do not compare them (ECDSA is randomized).",
            accountId: accountId.description, challenge: challenge, keys: keys,
            keyListDigest: AppAttestBinding.keyListDigest(registrations),
            appAttestClientData: String(decoding: AppAttestBinding.clientData(consumerId: accountId, challenge: challenge, keys: registrations), as: UTF8.self),
            appAttestClientDataHashHex: Hex.encode(AppAttestBinding.clientDataHash(consumerId: accountId, challenge: challenge, keys: registrations)),
            recoveryCredentialProof: ProofVector(subject: proof.subject.rawValue, subjectId: proof.subjectId, deviceId: proof.deviceId.description,
                                                 signedAt: ViadereDate.format(proof.signedAt), assurance: proof.assurance.rawValue,
                                                 publicKey: passcode.publicKey.base64URL,
                                                 signingInput: String(decoding: proof.signingInput(), as: UTF8.self), signature: proof.signature))
    }

    @Test func accountEnrollmentVectorsHold() async throws {
        let url = Self.vectorsDirectory.appendingPathComponent("account-enrollment-v1.json")
        if ProcessInfo.processInfo.environment["VIADERE_WRITE_VECTORS"] == "1" {
            try FileManager.default.createDirectory(at: Self.vectorsDirectory, withIntermediateDirectories: true)
            let encoder = JSONEncoder()
            encoder.outputFormatting = [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]
            try (try encoder.encode(try await Self.generate()) + Data("\n".utf8)).write(to: url)
        }
        let vectors = try JSONDecoder().decode(AccountEnrollmentVectors.self, from: try Data(contentsOf: url))
        let accountId = try #require(UUID(uuidString: vectors.accountId)).map { ConsumerID($0) }
        #expect(vectors.keys.count == DeviceKeyPurpose.allCases.count)
        var registrations: [DeviceKeyRegistration] = []
        for key in vectors.keys {
            let purpose = try #require(DeviceKeyPurpose(rawValue: key.purpose))
            let publicKey = try DevicePublicKey(base64URL: key.publicKey)
            // The signing input, recomputed from the inputs, is byte-identical.
            let message = DeviceEnrollment.proofMessage(consumerId: accountId, challenge: vectors.challenge, purpose: purpose, publicKey: publicKey)
            #expect(String(decoding: message, as: UTF8.self) == key.proofMessage)
            #expect(key.algorithm == "ES256")
            let registration = DeviceKeyRegistration(purpose: purpose, publicKey: publicKey, hardwareBacked: true, proof: key.proof)
            #expect(DeviceEnrollment.verify(registration, consumerId: accountId, challenge: vectors.challenge))
            // Bound to the reserved account id and the challenge.
            #expect(!DeviceEnrollment.verify(registration, consumerId: ConsumerID(), challenge: vectors.challenge))
            #expect(!DeviceEnrollment.verify(registration, consumerId: accountId, challenge: vectors.challenge + "x"))
            registrations.append(registration)
        }
        #expect(AppAttestBinding.keyListDigest(registrations) == vectors.keyListDigest)
        #expect(String(decoding: AppAttestBinding.clientData(consumerId: accountId, challenge: vectors.challenge, keys: registrations), as: UTF8.self)
            == vectors.appAttestClientData)
        #expect(Hex.encode(AppAttestBinding.clientDataHash(consumerId: accountId, challenge: vectors.challenge, keys: registrations))
            == vectors.appAttestClientDataHashHex)

        let p = vectors.recoveryCredentialProof
        let subject = try #require(ConfirmationProof.Subject(rawValue: p.subject))
        let assurance = try #require(DecisionAssurance(rawValue: p.assurance))
        let deviceId = try #require(UUID(uuidString: p.deviceId)).map { DeviceID($0) }
        let signedAt = try #require(ViadereDate.parse(p.signedAt))
        let proof = ConfirmationProof(subject: subject, subjectId: p.subjectId, deviceId: deviceId, signedAt: signedAt, assurance: assurance, signature: p.signature)
        #expect(String(decoding: proof.signingInput(), as: UTF8.self) == p.signingInput)
        try proof.verify(subject: .recoveryCredential, subjectId: p.subjectId, publicKey: try DevicePublicKey(base64URL: p.publicKey), now: signedAt)
    }
}

private extension UUID {
    func map<T>(_ transform: (UUID) -> T) -> T { transform(self) }
}
